tooltip.patternFunction:
var state = data.operational_state ? String(data.operational_state) : 'Unknown';
var colors = {
  'Normal': '#2e7d32',
  'Watch': '#fbc02d',
  'Investigate': '#f57c00',
  'Intervention': '#d32f2f'
};
var stateColor = colors[state] || '#64748b';
var stateText = (state === 'Watch' || state === 'Investigate') ? '#1e293b' : '#ffffff';
var num = function (value, digits) {
  var parsed = Number(value);
  return Number.isFinite(parsed) ? parsed.toFixed(digits) : '\u2014';
};
var time = function (value) {
  var parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return '\u2014';
  return new Date(parsed).toLocaleString();
};
var name = data.water_point || data.entityName || 'Water point';
var node = data.node_id || data.entityName || '';
return '<div style="min-width:232px;box-sizing:border-box;background:#ffffff;'
