settings.markdownTextFunction:
var e = data && data.length ? data[0] : {};
function pick(keys) {
  for (var i = 0; i < keys.length; i++) {
    var v = e[keys[i]];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
}
function esc(v) {
  return String(v == null ? '\u2014' : v).replace(/[&<>"]/g, function (c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];
  });
}
function coord(v, digits) {
  if (v == null || v === '') return 'Unavailable';
  var n = Number(v);
  return Number.isFinite(n) ? n.toFixed(digits) : 'Unavailable';
}
function when(v) {
  var n = Number(v);
  return Number.isFinite(n) && n > 0 ? new Date(n).toLocaleString() : 'Unavailable';
}
var node = pick(['node_id', 'entityName']);
var name = pick(['water_point', 'entityName']);
var districts = {
  'FSN-01': 'Kathmandu',
  'FSN-02': 'Kathmandu',
  'FSN-03': 'Lalitpur'
};
var district = districts[String(node)] || pick(['district']);
var lat = coord(pick(['latitude']), 5);
var lon = coord(pick(['longitude']), 5);
var coords = lat !== 'Unavailable' && lon !== 'Unavailable' ? lat + ', ' + lon : 'Unavailable';
var av = pick(['active']);
var connectivity = av === true || av === 'true' ? 'Active'
  : (av === false || av === 'false' ? 'Inactive' : 'Unavailable');
var last = when(pick(['lastActivityTime']));
var telemetry = when(pick(['ts']));
if (!node && !name && coords === 'Unavailable' && last === 'Unavailable' && telemetry === 'Unavailable') {
  return "<div class='meta-card'><div class='meta-empty'>Click a map marker to inspect a water point.</div></div>";
}
return '<div class="meta-card">'
  + '<div class="meta-head"><span class="meta-id">' + esc(node || '\u2014') + '</span>'
  + '<span class="meta-name">' + esc(name || 'Water point') + '</span></div>'
  + '<div class="meta-row"><span>District</span><b>'
  + (district ? esc(district) : 'Unavailable') + '</b></div>'
  + '<div class="meta-row"><span>Connectivity</span><b>' + connectivity + '</b></div>'
  + '<div class="meta-row"><span>Coordinates</span><b>' + coords + '</b></div>'
  + '<div class="meta-row"><span>Device activity</span><b>' + last + '</b></div>'
  + '<div class="meta-row"><span>Telemetry time</span><b>' + telemetry + '</b></div>'
  + '</div>';

