var e = data && data.length ? data[0] : {};
var raw = e.operational_state || e.State || '';
var state = String(raw).toLowerCase();
var palette = {
  normal: '#2e7d32',
  watch: '#fbc02d',
  investigate: '#f57c00',
  intervention: '#d32f2f'
};
var color = palette[state] || '#64748b';
var text = (state === 'watch' || state === 'investigate') ? '#1e293b' : '#ffffff';
var label = raw ? String(raw).toUpperCase() : 'UNAVAILABLE';
var response = state === 'intervention'
  ? '<div class="node-state-response"><b>RESPONSE REQUIRED</b>'
    + 'Stop supply &middot; Acknowledge Critical alarm &middot; '
    + 'Resample &middot; Resume after safe readings</div>'
  : '';
return '<div class="node-state" style="background:' + color + ';color:' + text + '">'
  + '<div class="node-state-kicker">CURRENT OPERATIONAL STATE</div>'
  + '<div class="node-state-value">' + label + '</div>'
  + response
  + '</div>';
